if(foodUI.submit(f))return;
if(f.id==='region-form'){const currency=get('currency'),city=get('city'),shop=get('shop'),oldCountry=C.cityInfo(region()).country,newCountry=C.cityInfo({city}).country;if(!C.currencies.includes(currency)||!C.cities.some(c=>c.id===city))throw Error('Choose a city and currency');pendingRegion={city,currency,shop,rate:1};if(state.profile&&oldCountry!==newCountry){modal(`<h2>Use ${esc(newCountry)} prices and recipes?</h2><p>Your own ingredients and recipes stay</p><div class="button-row">${btn('Use local prices','region-local','','primary')}${btn('Keep my current prices','region-keep','','outline')}</div>`);}else applyRegion('local');return;}
if(f.id==='foodfilters-form'){if(save('Food settings saved',()=>{Object.assign(state.profile,{allergies:data.getAll('allergies'),otherAllergy:get('otherAllergy').trim(),avoid:get('avoid'),diet:get('diet'),prepTime:Number(get('prepTime')),kitchen:data.getAll('kitchen')});state.plan=C.refreshMeals(state.plan,state.profile,state.favorites,state.mealLogs,today());}))close();return;}
