if(f.id==='tdee-form'){const values={...state.profile,...Object.fromEntries(data)};for(const key of ['height','weight','age','activity'])values[key]=Number(values[key]);const estimate=C.energyEstimate(values);if(!estimate)throw Error('Complete all calculator fields with valid adult measurements.');save('Targets saved',()=>{Object.assign(state.profile,values,{nutrition:'estimates'});state.plan.targets=estimate;});close();return;}
